# RFC-0087 E2 in a folder tree (RFC-0093): the package of a type is the module path
# of the folder module that declares it, then its nested modules.
using{/user@example.com/Kit}
using{/user@example.com/Kit/Shapes}
note := struct<persistable>{Text:string = "n"}
Saved<public> := module{
  slot<public> := struct<persistable>{Index:i64 = 0}
}
PointText<public>:string = ToJson(point{X := 3})
SizeText<public>:string = ToJson(size{W := 2})
NoteText<public>:string = ToJson(note{})
SlotText<public>:string = ToJson(Saved.slot{Index := 4})
BackX<public>:i64 = Attempt(FromJson[point][PointText].X, -1)
BackW<public>:i64 = Attempt(FromJson[size][SizeText].W, -1)
# A text that names another package is no value of the type.
Moved<public>:i64 = Attempt(FromJson[point]["\{\"$package_name\":\"//user@example.com/Kit\",\"x_X\":5\}"].X, -1)

point<public> := struct<persistable>{X:i64 = 0, Y:i64 = 0}
# A module a file of the folder declares.
Shapes<public> := module{
  size<public> := struct<persistable>{W:i64 = 1, H:i64 = 1}
}
